import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Jordan Pickford', position: 'GK', age: 31, club: 'Everton', bio: {"es":"Le gusta hacerse oír. James Tarkowski dice que su compañero de equipo del Everton es \"de gama alta\", pero \"las galletas... él y yo nos caemos constantemente. Grita mi nombre constantemente detrás de mí, así que lo miro constantemente y él simplemente me ladra para que le ladre a alguien más. Y nunca puedo entender realmente lo que está diciendo porque está a 40 metros de distancia, gritándome, gritándome. Yo digo: '¿Podrías venir y decirme lo que quieres?...\" El año pasado rompió el récord de portería a cero consecutiva en Inglaterra. Se habría llamado Jordan Pigford pero su padre, Lee, cambió el apellido porque estaba cansado de que lo llamaran Piggy en la escuela. Pickford dice que si no fuera futbolista, estaría en motocross. \"Crecí viéndolo. Cuando éramos niños, nos quedábamos en casas rodantes y caravanas en el hipódromo y era fantástico. Me da la adrenalina adecuada y es una de las cosas que me encantan\".","en":"Likes to make himself heard. James Tarkowski says his Everton teammate is “top-end” but “crackers … me and him fall out constantly. He shouts my name constantly from behind me so I'm constantly looking at him and he's just barking at me to bark at someone else. And I can never really understand what he's saying because he's 40 yards away, shouting, screaming at me. I'm like: 'Will you just come and tell me what you want’ …” Last year he broke the record for consecutive England clean sheets. He would have been called Jordan Pigford but his dad, Lee, changed the family name because he was tired of being called Piggy at school. Pickford says that if he wasn’t a footballer, he’d be in motocross. “I grew up watching it. We would stay in motorhomes and caravans at the racetrack as kids and it was mint. It gives me proper adrenaline, and it is one of the things I love.”"}, special: "No 1 goalkeeper" },
  { number: 13, name: 'Dean Henderson', position: 'GK', age: 28, club: 'Crystal Palace', bio: {"es":"Henderson dejó el Manchester United para unirse a Palace en 2023 después de un préstamo llamativo en Forest, y su reputación sigue creciendo. Lo más destacado hasta ahora incluye salvar el penalti de Omar Marmoush en Wembley para ayudar al Palace a ganar su primera Copa FA, algo que luego atribuyó a “mi gorra mágica... cuando me la puse supe que teníamos una oportunidad”. A menudo se le ve encabezando la canción tributo a Shakira de los fanáticos del Palace sobre esa victoria en la Copa durante y después de los juegos. Dice que le encanta ir a los campos de entrenamiento de Inglaterra porque \"a veces el primer día es una noche especial y comemos brownies y natillas. Eso siempre es algo que esperamos con ansias. Un día antes de un partido hay arroz con leche como postre. El arroz con leche de aquí es sensacional, tiene pequeñas chispas de chocolate blanco. Es algo que siempre espero con ansias\".","en":"Henderson left Manchester United to join Palace in 2023 after an eye-catching loan at Forest, and his reputation keeps growing. Highlights so far include saving Omar Marmoush’s penalty at Wembley to help Palace win their first FA Cup, which he later credited to “my magic cap … when I put it on I knew we had a chance”. He’s often seen leading Palace fans’ Shakira tribute song about that Cup victory during and after games. He says he loves going to England training camps because “sometimes day one is a special night and we get brownies and custard. That’s always something to look forward to. A day before a game is rice pudding for dessert. The rice pudding here is sensational, it’s got little white chocolate chips in it. It’s something I always look forward to.”"} },
  { number: 23, name: 'James Trafford', position: 'GK', age: 23, club: 'Manchester City', bio: {"es":"Regresó al City, donde comenzó a los 12 años, procedente del Burnley el año pasado, después de mantener 29 porterías a cero en 45 partidos de campeonato. Creció en la granja de sus padres en Cumbria, y su mudanza a la City en 2015 apareció en el periódico local, titulado: “James, 12 años, ficha por el Man City megarico”. Su padre le dijo al Times & Star: \"Nos ayuda a llevar las ovejas al campo; es uno de sus trabajos favoritos. Pero nunca he dicho que deba cultivar. Tienes que dejarlas seguir su propio camino... estamos muy orgullosos de él\". James junior dijo al periódico: \"No estoy nervioso. Los jugadores del primer equipo están en el mismo lugar donde entrenamos. He conocido a Gaël Clichy y Vincent Kompany, y he visto a Joe Hart entrenar. Es realmente emocionante\". Todavía mantiene la mano metida cada vez que regresa a su casa en la granja. \"La última vez que estuve con papá, estaba acomodando a todas las ovejas y preparando heno para las que estaban afuera. Siempre hemos hecho eso\".","en":"Returned to City - where he started aged 12 - from Burnley last year, after keeping 29 clean sheets in 45 Championship games. He grew up on his parents’ farm in Cumbria, and his move to City in 2015 made the local paper, headlined: “James, 12, signs for mega-rich Man City.” His dad told the Times & Star: “He helps us get the sheep into the field – it's one of his favourite jobs. But I've never said that he must farm. You've got to let them go their own way … we're extremely proud of him.” James junior told the paper: “I'm not nervous. The first-team players are in the same place we train. I've met Gaël Clichy and Vincent Kompany, and I've seen Joe Hart training. It's really exciting.\" He still keeps his hand in whenever he goes home to the farm. “When I was with dad last time I was bedding up all the sheep and putting hay out for the ones outside. We’ve always done that.”"}, special: "Farmer's son" },
  // Defensores
  { number: 2, name: 'Ezri Konsa', position: 'DF', age: 29, club: 'Aston Villa', bio: {"es":"Fichó por el Charlton a los 11 años tras empezar en el Senrab FC, el club de la Sunday League del Forest Gate de Londres del que también salieron, entre otros, Jermain Defoe, Sol Campbell y John Terry. Konsa tiene la palabra “bendito” tatuada en su mano izquierda. \"Lo obtuve en mi segunda temporada en Charlton\", dijo en 2021. \"Me recuerda lo lejos que he llegado y lo bendecido que soy. Fue difícil crecer donde crecí. Hubo mucho crimen y violencia, pero tengo suerte de tener un hermano mayor que me mantuvo fuera de problemas y me mantuvo con los pies en la tierra. Fue difícil, pero mi familia y mis amigos, yo, lo enfrentamos y salimos de ello. Ojalá lo que estoy haciendo ahora pueda inspirar a la próxima generación\". Fichó por Villa procedente de Brentford en 2019 por £ 12 millones e hizo su debut con Inglaterra contra Brasil en 2024. Tiene el respaldo real del príncipe William, fanático de Villa. Konsa: \"Una vez me llamó Rolls-Royce. Eso se me quedó grabado en la cabeza. Lo usaré todo el día. Fue realmente agradable\".","en":"Signed for Charlton at 11 after starting out at Senrab FC, the Sunday League club in London’s Forest Gate which also produced, among others, Jermain Defoe, Sol Campbell and John Terry. Konsa has the word “blessed” tattooed on his left hand. “I got it in my second season at Charlton,” he said in 2021. “It reminds me how far I’ve come and how blessed I am. It was difficult growing up where I grew up. There was a lot of crime and violence, but I am lucky to have an older brother who kept me out of trouble and kept me grounded. It was tough, but me and my family and friends dealt with it and we got out of it. Hopefully what I’m doing now can inspire the next generation.” He signed for Villa from Brentford in 2019 for £12m, and made his England debut against Brazil in 2024. Has royal backing from Villa fan Prince William. Konsa: “He called me a Rolls-Royce once. That got stuck in my head. I’ll take that all day. It was really nice.”"} },
  { number: 3, name: 'Nico O’Reilly', position: 'DF', age: 21, club: 'Manchester City', bio: {"es":"Graduado de la academia del City y firmado a los ocho años, el ascenso de O'Reilly ha sido rápido. Un debut completo en 2024, una primera convocatoria de Inglaterra un año después y ahora un Mundial. \"Es una locura, nunca pensé que estaría en esta posición tan pronto\", dijo el año pasado, insistiendo en que su gran avance no lo había cambiado. \"Todavía tengo los mismos amigos, sigo haciendo las mismas cosas, sigo yendo a Tesco con mi madre\". Él dice que mamá Holli es su inspiración, y ella le grabó un mensaje de video sorpresa cuando firmó su nuevo contrato con la ciudad en septiembre pasado, diciendo: \"Siempre recuerdo, cuando tenías unos tres meses, te miré y supe que eras especial. Le dije a Nana que él es especial y ella se rió de mí como lo hace, y dice que todos piensan que sus hijos son especiales. Pero hijo, sabía que lo eras, y siempre creí en ti, y siempre lo creerás. Nunca cambies. Estás destrozando la vida por completo, y te amo tú.”","en":"A City academy graduate having signed aged eight, O’Reilly’s rise has been rapid. A full debut in 2024, a first England call-up a year later, and now a World Cup. “It’s mad, I never thought I’d be in this position so soon,” he said last year, insisting his breakthrough hadn’t changed him. “I've still got the same friends, I still do the same stuff, I still go to Tesco with my mum.” He says mum Holli is his inspiration, and she recorded a surprise video message for him when he signed his new City contract last September, saying: “I always remember, when you were about three months old, I looked at you and I knew you were special. I said to Nana he is special and she laughed at me like she does, and says everyone thinks their kids are special. But son, I knew you were, and always believed in you, and always will. Don’t ever change. You’re absolutely smashing life, and I love you.”"}, special: "On the rise" },
  { number: 5, name: 'John Stones', position: 'DF', age: 32, club: 'Manchester City', bio: {"es":"Debutó con Inglaterra hace 12 años y lo ha ganado todo a nivel de clubes. \"Nunca pensé que sería profesional, y mucho menos jugar para Inglaterra, jugar en la Premier League, y mucho menos ganar la Premier League\", dijo en 2023. Graduado de la Academia Barnsley, conocido como el 'Barnsley Beckenbauer', siempre ha querido no ser visto como demasiado culto con el balón. “Por supuesto, lo colocaré en la fila Z si es necesario”, dijo hace una década después de su traslado del Everton por 47,5 millones de libras. \"Hago las cosas sucias que todo defensor debería hacer y en las que debería ser bueno. El resto es un bono, donde puedo jugar e iniciar ataques\". Es popular entre sus compañeros de equipo; El año pasado, su compañero de equipo del City, Bernardo Silva, reveló por qué le puso a su perro el nombre de Stones. \"Estaba pensando en tener un perro y le dije: 'John, un día, si tengo un perro, le pondré tu nombre. ¿Te alegraría?'","en":"Made his England debut 12 years ago, and has won everything at club level. “I never thought I'd be a professional, let alone playing for England, playing in the Premier League, never mind winning the Premier League,” he said in 2023. A Barnsley academy graduate, known as the ‘Barnsley Beckenbauer’, he’s always been keen not to be seen as too cultured on the ball. “Of course, I’ll kick it into Row Z if necessary,” he said a decade ago after his £47.5m move from Everton. “I do the dirty stuff that every defender should do and should be good at. The rest of it is a bonus, where I can play out and start attacks.” He’s popular among teammates; last year City teammate Bernardo Silva revealed why he named his dog after Stones. “I was thinking of getting a dog and I said: ‘John, one day if I get a dog, I will name it after you. Would you be happy about it?’ He said ‘no you can’t’. But then I just did it. I like the name John. John Silva, I think it’s a good name.”"} },
  { number: 6, name: 'Marc Guéhi', position: 'DF', age: 26, club: 'Manchester City', bio: {"es":"El segundo jugador de Inglaterra nacido en Costa de Marfil después de su excompañero en el Palace Wilfried Zaha. Dejó el Chelsea por el Palace, cedido en el Swansea, en 2021, y ganó allí la Copa FA. Hijo de un ministro de la iglesia, calificó el fallido traslado del verano pasado a Liverpool y su posterior traslado al City en enero: “El plan de Dios [está llegando] a su plena realización”. Conocido por ser tranquilo y reflexivo, pero tiene la vista puesta en un futuro diferente cuando se acabe el fútbol. \"Me encantaría ser un luchador de la WWE\", le dijo a la BBC. \"Crecer, ver WWE... Puede ser peligroso, pero en lo que respecta al rendimiento... Soy un buen charlatán frente al micrófono... haciendo que la gente crea que eres el malo o el bueno\". Pasa su tiempo libre leyendo o en el cine “porque ahora nadie va al cine, así que es lindo estar solo en el cine”, y tiene planes de volver a tocar la batería. \"Toqué la batería en la iglesia durante mucho tiempo. Toqué la batería en la escuela. No tengo una batería, pero realmente quiero una. Es una muy buena manera de disfrutar la música y escapar\".","en":"The second Côte d'Ivoire-born England player after his former Palace teammate Wilfried Zaha. Left Chelsea for Palace, via a loan at Swansea, in 2021, and won the FA Cup there. Son of a church minister, he called last summer’s collapsed move to Liverpool and subsequent move to City in January: “God’s plan [coming] to full fruition.” Known for being calm and thoughtful, but he has his eye on a different future when football’s over. “I'd love to be a WWE wrestler,” he told the BBC. “Growing up, watching WWE … It can be dangerous but the performance side of it … I'm a good waffler on the mic … making people believe you're the bad guy or the good guy.” Spends his spare time reading or in the cinema “because no one goes to the cinema now, so it's nice to be in a cinema on your own”, and has plans to resume drumming. “I drummed at church for a long time. I drummed at school. I don't have a drum set but I really want one. That's a really good way to enjoy music and escape.”"}, special: "Natural leader" },
  { number: 12, name: 'Tino Livramento', position: 'DF', age: 23, club: 'Newcastle', bio: {"es":"Livramento, nacido en Croydon, de padre portugués y madre escocesa, fue delantero del club de su infancia, Roundshaw, antes de unirse a la academia del Chelsea a los siete años. Se fue en 2021 antes de aparecer en el primer equipo y se unió al Southampton, donde sufrió una grave lesión del ligamento cruzado anterior y tardó un año en recuperarse. \"Mentalmente, me hizo pasar por muchas cosas\", dijo al Telegraph en 2024. \"Me hizo crecer enormemente. Tenía 19 años, ya vivía lejos de mi familia. Estaba pasando por muchas cosas. No sabía si iba a volver al mismo nivel o si podría mejorar\". Pero recuperó sus fuerzas y demostró que no había perdido nada, ganándose un traslado de £32 millones a Newcastle, donde los fanáticos modificaron su antiguo canto de Tino Asprilla en su honor. \"No me parezco en nada a Asprilla. Nunca he hecho nada salvaje en un campo de entrenamiento. Soy consciente de las historias sobre él, un poco de todos modos. No he hecho nada salvaje, no te preocupes por eso. Soy bastante aburrido, ¿sabes? Pero el cántico es increíble, cada vez que lo escucho quiero sonreír\".","en":"Croydon-born to a Portuguese dad and Scottish mum, Livramento was a striker for his boyhood club, Roundshaw, before joining Chelsea’s academy aged seven. He left in 2021 before making a first-team appearance, joining Southampton, where he suffered a serious ACL injury, taking a year to recover. “Mentally, it put me through a lot of things,” he told the Telegraph in 2024. “It made me grow up, massively. I was 19, I was already living away from my family. I was going through a lot of things. I didn’t know whether I was going to return to the same level or be able to improve.” But he rebuilt his strength and proved he’d lost nothing, earning a £32m move to Newcastle, where fans have tweaked their old Tino Asprilla chant in his honour. “I’m not anything like Asprilla. I’ve never done anything wild at a training ground. I’m aware of the stories about him, a little anyway. I’ve not done anything wild, don’t worry about that. I’m pretty boring you know. But the chant is amazing, every time I hear it I want to smile.”"} },
  { number: 15, name: 'Dan Burn', position: 'DF', age: 33, club: 'Newcastle', bio: {"es":"Publicado por Newcastle cuando tenía 11 años justo antes de Navidad de 2003. Burn dijo que era \"devastador\", pero \"fue bastante malo, si soy honesto\". A los 13 años le quedaban nueve dedos después de un accidente mientras escalaba una valla, y a los 16 trabajaba en Asda en Blyth empujando carritos. \"Normalmente, los muchachos que son elegidos para jugar en los equipos juveniles son elegidos alrededor de los 15 o 16 años. No terminé fichando por nadie. Fui a sexto grado y estaba empujando carritos. Si hubieras dicho entonces que estaría en la Premier League, me habría reído de ti\". Pero continuó fuera de la liga y Darlington lo contrató a los 17 años, iniciando un viaje que, en 2022, incluyó un regreso de £13 millones a Newcastle desde Brighton. Cuando anotó en la final de la Copa Carabao y ganó su primera convocatoria de Inglaterra en 2024, el Asda en Blyth enmarcó una chaqueta de alta visibilidad tipo carrito “Burn 33” en homenaje. Dean, gerente de la tienda: \"Esperamos que Dan nos visite pronto, junto con el trofeo\".","en":"Released by Newcastle aged 11 just before Christmas in 2003. Burn said it was “devastating” but “I was pretty crap, if I’m honest”. By 13 he was down to nine fingers after a fence-climbing accident, and at 16 he was working at Asda in Blyth pushing trolleys. “Normally the lads who are getting picked up to play in the youth teams are getting picked up around 15, 16. I didn’t end up signing for anyone. I went to sixth form and was pushing trolleys. If you had said then that I would be in the Premier League, I’d have laughed at you.” But he kept going in non-league and Darlington signed him at 17, starting a journey which, in 2022, featured a £13m return to Newcastle from Brighton. When he scored in the Carabao Cup final and won his first England call-up in 2024, the Asda in Blyth framed a “Burn 33” high-vis trolley-pusher jacket in tribute. Store manager Dean: “We’re hoping that Dan will pay us a visit soon, along with the trophy.”"} },
  { number: 24, name: 'Reece James', position: 'DF', age: 26, club: 'Chelsea', bio: {"es":"James, graduado de la academia del Chelsea, comenzó como delantero porque \"yo idolatraba a Didier Drogba... Él jugaba en mi equipo, jugaba en mi posición y siempre lo admiraba. Sólo quería ser como él, marcar como él y celebrar como él\". Pero sus entrenadores lo vieron de otra manera y lo trasladaron primero al centro del campo y luego, a los 15 años, al lateral derecho. “Lo odié durante dos o tres años, pero un día encajó”. Él y Lauren son los primeros hermanos en jugar fútbol senior en Inglaterra en la era moderna. Sin embargo, se dan espacio mutuamente. Lauren dijo en 2022: \"Cualquier cosa que tenga que ver con el fútbol, ​​ambos sabemos lo que tenemos que hacer, así que dejamos al otro a cargo. Pero fuera del fútbol, ​​tenemos una gran relación. Creo que nuestra diferencia de edad ayuda, ya que solo han sido dos años... Es un tipo divertido\". Superó tres temporadas difíciles de lesiones y problemas físicos para estar listo para este verano.","en":"A Chelsea academy graduate, James started out as a striker because “I idolised Didier Drogba … He played in my team, he played in my position and I always looked up to him. I just wanted to be like him, score like him and celebrate like him.” But his coaches saw it differently, moving him first to midfield, then, aged 15, to right-back. “I hated it for two or three years. But then one day it just clicked.” He and Lauren are the first brother and sister to play senior England football in the modern era. They give each other space, though. Lauren said in 2022: “Anything to do with football, we both know what we need to do so we just leave the other one to it. But outside of football, we have a great relationship. I think with our age gap that helps, with it only being two years … He is a funny guy.” He overcame three difficult seasons of injury and fitness problems to be ready for this summer."} },
  { number: 25, name: 'Djed Spence', position: 'DF', age: 25, club: 'Tottenham', bio: {"es":"Spence dice que mantiene una nota mental de todos sus escépticos. Los Spurs lo cedieron tres veces antes de establecerse, y también fue cedido cuando estaba en Middlesbrough en 2021, y el entonces entrenador Neil Warnock le advirtió que estaría en el fútbol fuera de la liga en cinco años a menos que cambiara su actitud. Después de ganar el ascenso con Forest, a quien se unió cedido por Boro, tuiteó una foto de sí mismo con el trofeo, fumando un cigarro y etiquetó a Warnock. \"No diría que tengo una lista en particular, pero sí tengo una nota mental de las personas que dudaron de mí, sin duda, y me hace sentir bien demostrarles que están equivocados\", dice. “Siempre tuve eso desde muy joven, siempre tuve que luchar por mi puesto”. Cuando debutó con Inglaterra el año pasado, se convirtió en el primer musulmán en hacerlo con la selección absoluta masculina. \"Es una bendición, es increíble. Realmente me sorprendió, la primera vez. Si yo puedo hacerlo, tú puedes hacerlo. Es [importante] no sólo para los niños musulmanes sino para cualquier niño de cualquier fe. Ponte a pensar en algo y podrás hacerlo, hombre\".","en":"Spence says he keeps a mental note of all his doubters. He was sent on loan three times by Spurs before establishing himself, and was also loaned out when he was at Middlesbrough in 2021, with then-manager Neil Warnock warning him he’d be in non-league football in five years unless he changed his attitude. After winning promotion with Forest, who he joined on loan from Boro, he tweeted a photo of himself with the trophy, smoking a cigar, and tagged Warnock. “I wouldn’t say I particularly have a list but I do have a mental note of people who doubted me, for sure, and it does feel good to prove them wrong,” he says. “I’ve always had that from a young age, I’ve always had to fight for my position.” When he made his England debut last year he became the first Muslim to do so for the senior men’s side. “It’s a blessing, it’s amazing. I was surprised, really, the first ever. If I can do it, you can do it. It’s [important] not just for Muslim kids but for any child of any faith. Put your mind to something and you can do it, man.”"}, special: "Never-say-die attitude" },
  { number: 26, name: 'Jarell Quansah', position: 'DF', age: 23, club: 'Bayer Leverkusen', bio: {"es":"Se unió al Liverpool a los cinco años, lo capitaneó en el nivel juvenil y entró en el primer equipo en 2023. Pero dos años después, después de 58 apariciones, se unió al Leverkusen por £ 30 millones y anotó a los cinco minutos de su debut en la Bundesliga. Dijo en marzo que irse a Alemania había sido \"una obviedad... Sólo quería jugar. Sentí que podía jugar al más alto nivel, la Bundesliga es una liga superior. Creo que tal vez tengas un presentimiento. Me tomé un tiempo para reflexionar sobre todo lo que estaba pasando en Liverpool, todo lo que pensé que podría haber hecho mejor y lo que realmente era mejor para mi carrera, eso fue todo. Cuando los muchachos de Leverkusen llegaron y vi todo lo que querían, creo que, desde ese momento, Sabía que era la decisión correcta\". Ganó su primer partido internacional con Inglaterra el año pasado contra Albania, y lo calificó como \"uno de los mejores días de mi vida\". Su hermano Keenan juega en Slough Town.","en":"Joined Liverpool aged five, captained them at youth level, and broke into the first team in 2023. But two years later, after 58 appearances, he joined Leverkusen for £30m and scored five minutes into his Bundesliga debut. He said in March that leaving for Germany had been a “no-brainer … I just wanted to play. I felt like I could play at the top level, the Bundesliga's a top league. I think you just have maybe a gut feeling. I took time to myself to reflect on everything that was going on at Liverpool, everything I thought I could've done better and what was best for my career really, that was it. When the Leverkusen guys came in and I saw everything that they wanted - I think, from that moment, I knew it was the right decision.\" He won his first England cap last year against Albania, calling it “one of the greatest days of my life”. His brother Keenan plays for Slough Town."} },
  // Volantes
  { number: 4, name: 'Declan Rice', position: 'MF', age: 27, club: 'Arsenal', bio: {"es":"El jugador británico más caro de todos los tiempos con £ 105 millones, justo por delante de £ 100 millones Jack Grealish. Rice salió de la academia del Chelsea a los 14 años y se unió al West Ham después de una prueba. Permaneció allí hasta 2023, después de convertirse en uno de los tres únicos capitanes de los Hammers, junto con Billy Bonds y Bobby Moore, que llevaron al club a un trofeo importante. Ahora campeón de la Premier League con el Arsenal, hizo tres apariciones con Irlanda antes de comprometerse con Inglaterra en 2019. También ama el golf y trabajó como modelo en la Semana de la Moda de Londres en 2024, vistiendo una chaqueta azul marino con una corbata blanca con cordones. \"¿Sabes qué? Fue tan bueno\", le dijo a Sky. \"Me encanta la moda, esto es realmente especial\". Ha hablado anteriormente sobre cómo desarrollar su propio estilo, después de crecer con \"mamá siempre diciéndome cómo vestirme... Siempre estoy buscando un par de pantalones que queden bien por encima de mis zapatos. Ni demasiado bajos ni demasiado altos. Eso es una cosa clave para mí, cómo se ajustan un par de pantalones a los zapatos\".","en":"The most expensive British player ever at £105m, just ahead of £100m Jack Grealish. Rice was released from Chelsea’s academy aged 14 and joined West Ham after a trial. He stayed there until 2023 having become one of only three Hammers captains, with Billy Bonds and Bobby Moore, to lead the club to a major trophy. Now a Premier League champion with Arsenal, he made three appearances for Ireland before committing to England in 2019. Also loves golf, and did some modelling at London Fashion Week in 2024, wearing a navy jacket with white lace-up tie. “You know what, it was so good,” he told Sky. “I love fashion, this is really special.” Has talked previously about developing his own look, after growing up with “mum always telling me how to dress … I’m always looking for a pair of trousers that sit above my shoes well. Not too low, not too high. That’s a key thing for me, how a pair of trousers sit on shoes.”"}, special: "Midfield engine" },
  { number: 8, name: 'Elliot Anderson', position: 'MF', age: 24, club: 'Nottingham Forest', bio: {"es":"Anderson, nacido en Whitley Bay, fue nombrado en el equipo senior de Escocia por primera vez en agosto de 2023, elegible para representarlos a través de su abuela. Pero poco después cambió de opinión. \"Dejé el campamento después de unos días y decidí que simplemente necesitaba más tiempo\", dijo después de ser llamado a la selección absoluta de Inglaterra el año pasado. \"No quería sumergirme en nada, así que estoy muy agradecido de haberlo hecho ahora. Definitivamente soy inglés. Es sólo que Inglaterra no me había convocado en todas las categorías cuando era más joven, así que pensé en aprovechar la oportunidad. Pero una vez que tuve la creencia de que era lo suficientemente bueno para jugar para Inglaterra, me di cuenta\". Newcastle lo vendió a Forest en 2024 para cumplir con las reglas de rentabilidad y sostenibilidad de la Premier League. Anderson es otro graduado del famoso Wallsend Boys Club, junto con Alan Shearer, Peter Beardsley y Michael Carrick. Su hermano mayor Wil apareció en la undécima temporada de Love Island, entró a la villa el día 12 y fue abandonado el día 37.","en":"Whitley Bay-born Anderson was named in the senior Scotland squad for the first time in August 2023, eligible to represent them through his grandmother. But he changed his mind soon after. “I left camp after a few days and decided I just needed more time,” he said after being called into the senior England squad last year. “I didn’t want to dive into anything, so I’m really thankful I’ve done that now. I’m definitely English. It’s just I hadn’t really been called up by England through the age levels when I was younger so I thought I’d take the opportunity. But once I got that belief that I was good enough to play for England, it hit me.” Newcastle sold him to Forest in 2024 to meet Premier League profitability and sustainability rules. Anderson is another graduate of the famous Wallsend Boys Club, alongside Alan Shearer, Peter Beardsley and Michael Carrick. His older brother Wil appeared on the 11th season of Love Island, entering the villa on Day 12, and being dumped on Day 37."} },
  { number: 10, name: 'Jude Bellingham', position: 'MF', age: 23, club: 'Real Madrid', bio: {"es":"Criado en Stourbridge, Bellingham solía presentarse en Birmingham para entrenar cuando tenía 14 años con su uniforme burdeos de Priory School. El delantero Lukas Jutkiewicz dijo: \"Estamos haciendo ejercicios de remate y este chico se une al primer equipo, finge disparar, pone a los profesionales de alto nivel sobre sus traseros, lo corta y luego lo hace rodar hacia la otra esquina. Pensé, y sé que no era el único, '¿Quién es este?'\" Bellingham se graduó de Loughborough College con un Certificado BTec Nivel 3 en Deporte en 2021, y lo completó de forma remota después. Trasladándose al Borussia Dortmund. Los acuerdos comerciales incluyen Louis Vuitton, Lucozade, su propia colección exclusiva de JB Adidas, su propia aplicación y, en 2024, modelar calzoncillos masculinos para la marca Skims de Kim Kardashian. Tuvo un momento incómodo con Thomas Tuchel el año pasado cuando el técnico de Inglaterra contó a TalkSport sobre la \"ventaja\" de Bellingham durante los partidos que \"pueden ser un poco repulsivos\". Tuchel aclaró más tarde: \"Usé esta palabra sin querer. No había ningún mensaje, ni agenda oculta. Yo creé los titulares y lamento el disgusto. Debería haberlo sabido mejor\".","en":"Raised in Stourbridge, Bellingham used to turn up at Birmingham for training aged 14 in his burgundy Priory School uniform. Striker Lukas Jutkiewicz said: “We’re doing finishing drills and this kid’s joining in with the first-team, he’s faking to shoot, putting senior pros on their arses, chopping and then rolling it into the other corner. I thought to myself – and I know I wasn’t the only one – ‘Just who is this?’” Bellingham graduated from Loughborough College with a BTec Level 3 Certificate in Sport in 2021, completing it remotely after moving to Borussia Dortmund. Commercial deals include Louis Vuitton, Lucozade, his own JB Adidas signature collection, his own app, and, in 2024, modelling men’s underpants for Kim Kardashian’s Skims brand. He had an uneasy moment with Thomas Tuchel last year when the England manager told TalkSport about Bellingham’s “edge” during games which “can be a bit repulsive”. Tuchel clarified later: “I used this word unintentionally. There was no message, no hidden agenda. I created the headlines and I’m sorry for the upset. I should have known better.”"}, special: "Super star" },
  { number: 14, name: 'Jordan Henderson', position: 'MF', age: 36, club: 'Brentford', bio: {"es":"Un líder vocal, recién salido de una convincente temporada de regreso al fútbol inglés con el Brentford. Fue fuertemente criticado en 2023 después de dejar el Liverpool para ir al club Al-Ettifaq de la Liga Pro saudí, dado su apoyo anterior a los derechos LGBTQ+, y poco después fue abucheado por los aficionados durante un partido de Inglaterra. Terminó su contrato con Arabia Saudita después de 24 semanas y se mudó al Ajax, pero quedó fuera del equipo de la Eurocopa 2024. Cuando Inglaterra llegó a la final, llamó a una empresa de alquiler de furgonetas e hizo un viaje de siete horas hasta Berlín con su familia para verlo, sorprendiendo a los aficionados ingleses en las estaciones de servicio a lo largo del camino. \"Cuando necesitábamos el baño o algo así, o entrar en los garajes, era muy divertido ver a algunos de los fans\", dice. \"En realidad, fue muy agradable estar con ellos. Pero obviamente hubiera preferido estar con el equipo\". Obtuvo una retirada internacional en marzo pasado. Se le otorgó un MBE en 2021 por ayudar a impulsar la campaña de recaudación de fondos del NHS #PlayersTogether durante la pandemia de Covid.","en":"A vocal leader, fresh from a convincing comeback season in English football with Brentford. Was heavily criticised in 2023 after leaving Liverpool for Saudi Pro League club Al-Ettifaq, given his previous support for LGBTQ+ rights, and was booed by fans during an England game soon after. He ended his Saudi  contract after 24 weeks and moved to Ajax, but was left out of the Euro 2024 squad. When England made the final, he called a van-hire company and made the seven-hour journey to Berlin with his family to watch, surprising England fans at service stations along the way. “When we needed the toilet or something, or popping in the garages, it was quite funny to see some of the fans,” he says. “Actually, it was quite nice to be with them. But obviously I would have rather been with the team.” He earned an international recall last March. Was awarded an MBE in 2021 for helping drive the #PlayersTogether NHS fundraising campaign during the Covid pandemic."}, special: "Veteran" },
  { number: 16, name: 'Kobbie Mainoo', position: 'MF', age: 21, club: 'Manchester United', bio: {"es":"Cuando Mainoo se convirtió en 2024 en el primer adolescente inglés en marcar en una final de la Copa FA en 43 años, Paul Scholes escribió en Instagram: \"Lea algunas comparaciones entre este niño y yo. No pierdan el tiempo, es 10 veces más jugador que yo cuando tenía 19 años\". Su evolución en el United fue fluida hasta que se topó con el 3-4-2-1 de Rubén Amorim. Su medio hermano, la ex estrella de Love Island, Jordan Mainoo-Hames, usó una camiseta que decía “Kobbie Mainoo gratis” durante un empate 4-4 con Bournemouth, pero el fútbol normal no volvió hasta que Amorim se fue. Restaurado por Michael Carrick, que había trabajado con él en las categorías inferiores, Mainoo demostró su valía. \"Cuando hay nuevos entrenadores, ellos tienen la forma en que quieren jugar\", dijo Mainoo en mayo, reflexionando sobre su tiempo en el exilio. \"Si creen que no encajas en eso, entonces no encajas en eso. Yo diría que mi familia y mis amigos me ayudaron a ver la luz al final del túnel. Sabían que en algún momento volvería a mi favor. Sólo tenía que ser paciente\".","en":"When Mainoo became the first English teenager to score in an FA Cup final for 43 years in 2024, Paul Scholes wrote on Instagram: “Read a few comparisons between me and this kid. Don’t waste your time, he is 10 times the player I was at 19.” His progress at United was smooth until he came up against Ruben Amorim’s 3-4-2-1. His half-brother, the former Love Island star Jordan Mainoo-Hames, wore a “free Kobbie Mainoo” T-shirt during a 4-4 draw with Bournemouth, but regular football didn’t come again until Amorim left. Restored by Michael Carrick, who had worked with him at youth level, Mainoo proved his worth. “When there's new managers, they have their way they want to play,” Mainoo said in May, reflecting on his time in exile. “If they think you don't fit that, then you don't fit that. I'd say my family and my friends helped me see the light at the end of the tunnel. They knew it would swing back my way at some point. I just had to be patient.\""} },
  { number: 17, name: 'Morgan Rogers', position: 'MF', age: 23, club: 'Aston Villa', bio: {"es":"Rogers dice que sus períodos de préstamo en Lincoln, Bournemouth y Blackpool, antes de mudarse a Middlesbrough en 2023, “lo fueron todo para mí”. Le dijo a The Times: \"Tuve que pasar por muchas luchas, mucho dolor, muchos días difíciles... Tuve que encontrarme a mí mismo como jugador, y tuve que descubrirlo en las ligas inferiores, lo que funciona en un juego profesional, porque lo que funciona en el fútbol académico [de Man City] no es lo mismo en la Liga Uno o en el Campeonato\". Se mudó a Villa por £ 8 millones en 2024. Dice que era \"un poco geek en conocimientos de fútbol\" cuando era niño: \"Aprender jugadores, aprender equipos y esas cosas. Mi padre y yo éramos bastante buenos en esto: él me hacía preguntas y yo las respondía. Podía nombrar jugadores aleatorios en todo el mundo y esas cosas. Intentaba ser la persona más inteligente de la sala en lo que respecta al fútbol\". Tiene varios tatuajes, incluido uno en el antebrazo izquierdo que enumera los cumpleaños de sus padres y tres hermanos. \"Ese es mi favorito. El más sentimental\".","en":"Rogers says his loan spells at Lincoln, Bournemouth and Blackpool – before his move to Middlesbrough in 2023 – “were everything to me”. He told The Times: “I had to go through a lot of struggles, a lot of pain, a lot of hard days … I had to find myself as a player, and I had to find that out in the lower leagues – what works in a professional game – because what works in [Man City] academy football is not the same in League One or the Championship.” He moved to Villa for £8m in 2024. He says he was “a bit of a geek for football knowledge” as a boy: “Learning players, learning teams and stuff. Me and my dad were quite big on it – he’d ask me questions and I’d answer them. I’d be able to name random players across the world and stuff. I’d try and be the cleverest person in the room when it came to football.” He has multiple tattoos, including one on his left forearm listing the birthdays of his parents and three brothers. “That is my favourite one. My most sentimental one.”"}, special: "One to watch" },
  { number: 21, name: 'Eberechi Eze', position: 'MF', age: 28, club: 'Arsenal', bio: {"es":"El verano pasado, Eze estaba volando: ganador de la Copa FA con el Crystal Palace, un habitual emergente de Inglaterra y un nuevo fichaje de £ 60 millones para el club de la infancia, el Arsenal. Pero, aparte de un triplete memorable en el derbi contra los Spurs y dos en el partido de vuelta, ha tenido dificultades para generar un impacto regular en una temporada en la que ganó el título en los Emirates. Pero tiene mucha resiliencia a la que recurrir, ya que pasó por el trauma de ser cortado por varios clubes, incluido el Arsenal, cuando era joven. Mirando hacia atrás, dijo que se las arregló gracias a \"mi confianza y fe en Dios, simplemente permití que me alimentara y me llenara, lo cual era importante. No significa que no fuera difícil. Todavía es difícil superar esos momentos. Recuerdo haber pensado: '¿por qué es tan difícil? Pero el amor por el fútbol nunca, nunca cambió\". También es un entusiasta jugador de ajedrez, ya que su ex compañero de equipo en Palace, Michael Olise, le enseñó a jugar. Eze ganó el primer premio de £15.000 en un torneo amateur de Chess.com en mayo del año pasado, venciendo al YouTuber Sapnap en la final.","en":"Last summer Eze was flying: an FA Cup winner with Crystal Palace, an emerging England regular, and a new £60m signing for boyhood club Arsenal. But – apart from a memorable derby hattrick against Spurs, and two in the return fixture – he has struggled to make a regular impact in a title-winning season at the Emirates. But he has plenty of resilience to draw on, having been through the trauma of being released by multiple clubs, including Arsenal, as a youngster. Looking back he said he coped thanks to “my trust and faith in God, I just allowed it to fuel me and fill me up, which was important. It doesn't mean that it wasn’t difficult. It's still difficult to get through those times. I remember thinking: ‘why is this so hard? But the love for football never, never changed.” He’s also a keen chess player, having been taught to play by former Palace teammate Michael Olise. Eze won the £15,000 first prize in a Chess.com amateur tournament in May last year, beating YouTuber Sapnap in the final."}, special: "Chess player" },
  // Delanteros
  { number: 7, name: 'Bukayo Saka', position: 'FW', age: 25, club: 'Arsenal', bio: {"es":"Se siente como un miembro permanente de las selecciones inglesas, ya que debutó hace seis años, pero todavía tiene sólo 24 años. Su nombre, elegido por su abuela nigeriana, significa “añade a la felicidad”; Su apodo, “Little Chilli”, se lo puso su ex compañero de equipo Pierre-Emerick Aubameyang debido a sus picantes tiros en los entrenamientos. \"Siguió llamándome así y luego se convirtió en algo, y ahora es algo grande\". En 2024, Nandos lanzó una salsa Peri Peri Saka oficial, y Saka dijo: \"He ido a Nando's desde que era pequeño, así que tener mi propia salsa Peri-Peri es una locura\". El año pasado, durante tres meses con un desgarro en el tendón de la corva, se compró un nuevo cachorro, Tucker el cockapoo, y se dedicó a leer, y un libro en particular, El poder del ahora: una guía para la iluminación espiritual, de Eckhart Tolle, le tocó la fibra sensible. \"A veces pienso: 'Oh, ¿voy a volver en la mejor forma?' O, en el pasado: '¿Qué podría haber hecho para evitar lesiones?'","en":"Feels like a long-term fixture in England squads, having made his debut six years ago, but is still only 24. His first name, chosen by his Nigerian grandmother, means “adds to happiness”; his nickname, “Little Chilli”, was given to him by former teammate Pierre-Emerick Aubameyang due to his spicy shooting in training. “He just kept calling me it and then it became a thing, and now it's a big thing.” In 2024 Nandos brought out an official Peri Peri Saka sauce, with Saka saying: “I’ve been going to Nando’s since I was little so to have my own Peri-Peri sauce is quite mad.” During three months out with a torn hamstring last year he bought a new puppy, Tucker the cockapoo, and got stuck into reading, with one book in particular, Eckhart Tolle’s The Power of Now: A Guide to Spiritual Enlightenment, striking a chord. “Sometimes I’d think: ‘Oh, am I going to come back in the best shape?’ Or, in the past: ‘What could I have done to prevent injury?’ But all that is not necessary. One of the best things I took from the book is to always ask yourself: what’s necessary in this moment right now? And try to live that way.”"}, special: "Lightning quick" },
  { number: 9, name: 'Harry Kane', position: 'FW', age: 33, club: 'Bayern Munich', captain: true, bio: {"es":"Superó el récord goleador internacional de Pelé el año pasado, pero no fue hasta el verano pasado que finalmente levantó un trofeo de club, cuando el Bayern ganó su 34ª Bundesliga. “Fue un peso para mí”, dijo. \"A medida que pasan los años, empiezas a pensar: '¿Va a suceder?'\". Fue un camino difícil hasta la cima: a los 19 años fue cedido al Norwich, se perdió una niñera en su debut, jugó cinco veces y no marcó ningún gol. También tuvo dificultades durante su cesión en Leicester, lo que motivó en parte la creación de la Fundación Harry Kane, que apoya a organizaciones benéficas de salud mental. \"No había una línea recta hacia la cima [para mí]. Tuve que pasar por momentos realmente difíciles. Estoy aprendiendo cada vez más [sobre salud mental] y seguro que es algo que realmente intentaré asumir y ayudar tanto como pueda cuando mi carrera haya terminado\". En su tiempo libre juega al golf, colecciona relojes y juega al ajedrez, inspirado al ver The Queen's Gambit. Le dijo a GQ en 2024: \"Desde que salió, he empezado a aprender y tengo una puntuación de alrededor de 1200 en la versión de 10 minutos de Chess.com. Es bastante decente\".","en":"Overtook Pelé’s international scoring record last year, but it wasn’t until last summer that he finally lifted a club trophy, when Bayern won their 34th Bundesliga. “It was a weight on me,” he said. “As the years go by you start to think: ‘Is it going to happen?’” It was a rough road to the top: at 19 he was loaned to Norwich, missed a sitter on his debut, played five times, scored no goals. He also had a hard time on loan at Leicester – which partly motivated his creation of the Harry Kane Foundation, supporting mental health charities. “There wasn’t just a straight line to the top [for me]. I had to really go through some tough times. I’m learning more and more [about mental health] and for sure it’s something that I’ll really try to take on and help as much as I can when my career has finished.” In his spare time he plays golf, collects watches and plays chess, inspired by watching The Queen's Gambit. He told GQ in 2024: “Since that came out I've started to learn and I'm about 1200 rated on the 10-minute version on Chess.com. It's fairly decent.”"}, special: "Goal machine" },
  { number: 11, name: 'Marcus Rashford', position: 'FW', age: 28, club: 'Manchester United', bio: {"es":"Titular de un MBE, autor y activista contra la pobreza que se enfrentó y venció a Boris Johnson dos veces. Rashford llegó al Mundial en lo más alto tras una temporada reparadora en el Barcelona. En octubre pasado señaló la alta rotación de entrenadores en el Manchester United como una razón de su inconsistencia allí: \"Siento que he estado en un ambiente inconsistente durante mucho tiempo... Para ser consistente en cualquier cosa, no sólo en el deporte, necesitas variables consistentes en tu vida. Hemos tenido tantos cambios\". Se crió en Wythenshawe, el menor de cinco hermanos, y su madre, Mel, tenía tres trabajos para mantener a la familia. Sus experiencias influyeron en su trabajo fuera del campo desde entonces. Coescribió la serie de libros The Breakfast Club Adventures y el bestseller de autoayuda para niños You Are A Champion. Comienza con esta dedicatoria: \"A cada joven que intenta encontrar su camino. A mi madre, por ayudarme a creer que los sueños pueden hacerse realidad\".","en":"MBE-holder, author and poverty campaigner who took on and beat Boris Johnson twice. Rashford arrived at the World Cup on a high after a restorative season at Barcelona. Last October he pointed to the high turnover of managers at Manchester United as a reason for his inconsistency there: “I feel like I’ve been in an inconsistent environment for a long time … In order to be consistent in anything, not just sport, you need consistent variables in your life. We’ve just had so many changes.” He was raised in Wythenshawe, the youngest of five, with his mum, Mel, working three jobs to keep the family going. His experiences informed his off-field work since. He co-wrote The Breakfast Club Adventures book series, and the self-help bestseller for children You Are A Champion. It starts with this dedication: “To every young person who is trying to find their way. To my mum, for helping me believe that dreams can come true.”"}, special: "Social campaigner" },
  { number: 18, name: 'Anthony Gordon', position: 'FW', age: 25, club: 'Newcastle', bio: {"es":"Llega a la Copa del Mundo gracias a una de las transferencias más sorprendentes de los últimos años, ya que el Barcelona pagó £60,7 millones más complementos para ficharlo procedente del Newcastle. Se mostró optimista durante su presentación diciendo: \"Hay un fuego ardiente en mi estómago por ganar aquí. [Aporto] mi intensidad, ritmo de trabajo, habilidad técnica. Me gusta marcar goles, asistir y ayudar al equipo a ganar partidos\". Es un gran cambio para un jugador que, liberado por el Liverpool a los 11 años, se unió al Everton y permaneció hasta 2023 cuando, a través de una controvertida solicitud de transferencia, se unió al Newcastle por £40 millones. Su debut con la selección absoluta en Inglaterra se produjo contra Brasil en 2024. Es fanático de los libros motivacionales, entre cuyos favoritos se incluyen Winning: The Unforgiving Race to Greatness de Tim Grover y Never Finished: Unshackle Your Mind and Win the War Within del retirado Navy Seal y corredor de ultramaratones David Goggins. Durante la Eurocopa 2024, apareció de manera memorable en una conferencia de prensa habitual en Inglaterra cubierto de cortes después de haberse caído de una bicicleta eléctrica mientras intentaba grabar un vídeo con su teléfono, habiendo entendido mal los descansos. \"La bicicleta no sólo ha disminuido la velocidad, sino que se ha detenido por completo... y yo no\".","en":"Arrives at the World Cup on the back of one of the most surprising transfers in recent years as Barcelona paid £60.7m plus add-ons to sign him from Newcastle. He was bullish during his presentation saying “There is a burning fire in my belly to win here. [I bring] my intensity, work rate, technical ability. I like to score goals, assist and help the team win games.” It is quite a turnaround for a player who, released by Liverpool aged 11, joined Everton and stayed until 2023 when, via a controversial transfer request, he joined Newcastle for £40m. His senior England debut came against Brazil in 2024. He’s a fan of motivational books, with favourites including Winning: The Unforgiving Race to Greatness by Tim Grover and Never Finished: Unshackle Your Mind and Win the War Within by the retired Navy Seal and ultra-marathon runner David Goggins. During Euro 2024 he memorably turned up to face a regular England press conference covered in cuts having fallen off an electric bike while trying to take a video on his phone, having misunderstood the breaks. “The bike has not just slowed down, it has fully come to a stop … and I haven’t.”"} },
  { number: 19, name: 'Ollie Watkins', position: 'FW', age: 31, club: 'Aston Villa', bio: {"es":"Marcó el gol de último minuto que llevó a Inglaterra a la final de la Eurocopa 2024. \"No creo haber golpeado una pelota tan dulce antes\". Dijo que se sentía surrealista para alguien que, unos años antes, había estado luchando por ingresar al lado de Exeter en la Liga Dos. \"Nunca lo imaginé. Obviamente se puede soñar, pero yo soy realista\". Su rutina previa al partido incluye música: \"Cuanto más se acerca el inicio, me gusta escuchar hip-hop más pesado, así que 50 Cent y su álbum de la vieja escuela Get Rich or Die Tryin' o Rick Ross, algo así\". Pero optó por cantar Never Too Much de Luther Vandross como canción de iniciación al fichar por el Villa. Su amor por la música se lo debe su madre, Delsi-May, una cantante profesional, quien le contó al Times en 2021 cómo descubrió por primera vez el potencial futbolístico de Ollie junto al mar en su casa en Torquay. \"Solíamos sacar a los niños y había una pequeña máquina en la que metías un 2p y se caía una pequeña pelota de goma. Él se paraba allí, la dejabas caer y él la pateaba. Nunca fallaba. Sólo tenía nueve meses\".","en":"Scored the last-minute goal that sent England to the Euro 2024 final. “I don’t think I’ve hit a ball that sweet before.” He said it felt surreal for someone who, a few years earlier, had been struggling to get into Exeter’s side in League Two. “I never imagined it. Obviously you can dream but I’m a realist.” His pre-match routine involves music: “The closer it gets to kick-off, I like to listen to heavier hip-hop, so 50 Cent and his old school Get Rich or Die Tryin' album or Rick Ross – something like that.” But he chose to sing Never Too Much by Luther Vandross as his initiation song when signing for Villa. Gets his love of music from his mum, Delsi-May, a professional singer, who told the Times in 2021 how she first spotted Ollie’s football potential by the seaside at home in Torquay. “We used to take the kids out, and there was a little machine where you put a 2p in, and a little rubber ball fell out. He’d stand there and you’d drop it, and he’d kick it. He never used to miss. He was only nine months old.”"}, special: "Music lover" },
  { number: 20, name: 'Noni Madueke', position: 'FW', age: 23, club: 'Arsenal', bio: {"es":"Fichado por Crystal Palace cuando tenía nueve años, se mudó a los Spurs tres años después y, después de brillar en las categorías inferiores de Inglaterra, el Manchester United se acercó a él. Pero los rechazó y optó por dejar Inglaterra a los 16 años para fichar por el PSV Eindhoven. \"Sólo quería integrarme en la configuración del primer equipo lo más rápido posible\". Le dijo a GQ que aprendió holandés rápidamente porque \"no quería que nadie hablara mierda de mí en el campo... Como, '¡Sé exactamente lo que estás diciendo!'\". Brilló allí y el Chelsea lo contrató del PSV por £28,5 millones en 2023. El Arsenal pagó £48,5 millones por él en 2025, un trato criticado por algunos fanáticos del Arsenal con una campaña #NoToMadueke debido a su forma mixta y la tarifa. \"Lo tomé con calma. Estás en el ojo público, la gente puede decir lo que quiera\". Es uno de los fanáticos de la moda de la selección inglesa. \"Siento que si te ves bien, te sientes bien, juegas bien. El fútbol, ​​la música, la moda, todo está conectado para mí. Así es como expreso quién soy, y cada uno se alimenta del otro\".","en":"Signed by Crystal Palace when he was nine, he switched to Spurs three years later and, after starring at England youth levels, was approached by Manchester United. But he rejected them, opting instead to leave England aged 16 for PSV Eindhoven. “I just wanted to be integrated into a first-team setup as quickly as possible.” He told GQ he learnt Dutch quickly because “I didn't want anyone talking shit about me on the field … Like, ‘I know exactly what you're saying!’” He shone there, and Chelsea signed him from PSV for £28.5m in 2023. Arsenal paid £48.5m for him in 2025 – a deal criticised by some Arsenal fans with a #NoToMadueke campaign due to his mixed form, and the fee. “I took it in my stride. You are in the public eye, people can say what they want.” He’s one of the England squad’s fashion fans. “I feel like if you look good, you feel good, you play good. Football, music, fashion, it’s all connected for me. It’s how I express who I am, and each one feeds into the other.”"} },
  { number: 22, name: 'Ivan Toney', position: 'FW', age: 30, club: 'Al-Ahli', bio: {"es":"La gran sorpresa en el equipo de Thomas Tuchel, al menos para la mayoría de la gente, pero tal vez no para el hombre mismo. Tras dejar Brentford por Al-Ahli en 2024, le dijo a The Guardian al año siguiente que el nivel del fútbol en la Saudi Pro League estaba \"a la par con la Premier League... Si Al-Ahli estuviera en la Premier League, estaríamos cerca de los cuatro primeros. La gente no debería mirar hacia arriba\". Su experiencia jugando en el calor podría haberlo ayudado a superar a Dominic Calvert-Lewin, Dominic Solanke y Danny Welbeck por un lugar en este equipo. Dice que los críticos deberían “ir e intentar jugar en una sauna y ver si pueden arreglárselas”. Se perdió la Copa del Mundo de 2022 debido a la investigación sobre violaciones de las reglas de apuestas de la FA que llevaron a una suspensión de ocho meses. \"El mayor castigo para mí fue perderme la Copa del Mundo\", dijo en 2023. \"Sentí que alguien quería impedirme jugar con Inglaterra. Ese fue el punto más bajo\". Famoso por su técnica de penalti sin mirar, incluida una durante la tanda de penaltis de la Eurocopa 2024. “Nunca miro el balón”, dijo más tarde. \"Algunas personas pueden considerarlo una locura, pero es sólo mi rutina\".","en":"The big surprise in Thomas Tuchel’s squad – to most people at least, but maybe not to the man himself. Having left Brentford for Al-Ahli in 2024 he told the Guardian the following year that the level of football in the Saudi Pro League was “on a par with the Premier League … If Al-Ahli were in the Premier League, we’d be close to the top four. People shouldn’t turn their noses up.” His experience of playing in the heat could have helped him edge out Dominic Calvert-Lewin, Dominic Solanke and Danny Welbeck for a place in this squad. He says critics should “go and try to play in a sauna and see if they can cope.” He missed the 2022 World Cup due to the investigation into breaches of FA betting rules which led to an eight-month ban. “The biggest punishment for me was missing out on the World Cup,” he said in 2023. “I felt like somebody's out to get me to stop me from playing for England. That was the lowest point.” Famed for his no-look penalty technique, including one during a shoot-out in Euro 2024. “I never look at the ball,” he said later. “Some people may see it as crazy. But it is just my routine.”"}, special: "Surprise call-up" },
];

